namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = [];

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.AddRange(
        [
            new(NextId(), "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)),
            new(NextId(), "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)),
            new(NextId(), "New feature available: Dark Mode.", DateTime.UtcNow.AddMinutes(-2)),
        ]);
    }

    public Task<List<Notification>> GetNotificationsAsync()
        => Task.FromResult(_notifications.ToList());

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastSeenId)
    {
        // Simulate new notifications arriving occasionally
        if (Random.Shared.NextDouble() < 0.3)
        {
            _notifications.Add(new(NextId(), $"New alert at {DateTime.UtcNow:T}.", DateTime.UtcNow));
        }

        var newer = _notifications.Where(n => n.Id > lastSeenId).ToList();
        return Task.FromResult(newer);
    }

    private int NextId() => _nextId++;
}

@page "/notifications"
@rendermode InteractiveServer
@inject BlazorApp.Services.NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (_notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
    }
</h1>

@if (_notifications is null)
{
    <p><em>Loading…</em></p>
}
else if (_notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("g")</small>
            </li>
        }
    </ul>
}

@code {
    private List<BlazorApp.Services.Notification>? _notifications;
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<BlazorApp.Services.Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Restore from prerender state if available; otherwise fetch once.
        if (PersistedNotifications is not null)
        {
            _notifications = PersistedNotifications;
        }
        else
        {
            _notifications = await NotificationService.GetNotificationsAsync();
            PersistedNotifications = _notifications;
        }
    }

    protected override Task OnAfterRenderAsync(bool firstRender)
    {
        // OnAfterRender is never called during prerender, so the polling
        // loop only starts once the page is truly interactive.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }

        return Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var lastId = _notifications?.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;

            var newer = await NotificationService.GetNotificationsSinceAsync(lastId);

            if (newer.Count > 0)
            {
                _notifications ??= [];
                _notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

