+@page "/notifications"
+@rendermode InteractiveServer
+@inject BlazorApp.Services.NotificationService NotificationService
+@implements IAsyncDisposable
+
+<PageTitle>Notifications</PageTitle>
+
+<h1>
+    Notifications
+    @if (_notifications is not null)
+    {
+        <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
+    }
+</h1>
+
+@if (_notifications is null)
+{
+    <p><em>Loading…</em></p>
+}
+else if (_notifications.Count == 0)
+{
+    <p>No notifications.</p>
+}
+else
+{
+    <ul class="list-group">
+        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-center">
+                @n.Message
+                <small class="text-muted">@n.Timestamp.ToString("g")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    private List<BlazorApp.Services.Notification>? _notifications;
+    private CancellationTokenSource? _cts;
+
+    [PersistentState]
+    public List<BlazorApp.Services.Notification>? PersistedNotifications { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        // Restore from prerender state if available; otherwise fetch once.
+        if (PersistedNotifications is not null)
+        {
+            _notifications = PersistedNotifications;
+        }
+        else
+        {
+            _notifications = await NotificationService.GetNotificationsAsync();
+            PersistedNotifications = _notifications;
+        }
+    }
+
+    protected override Task OnAfterRenderAsync(bool firstRender)
+    {
+        // OnAfterRender is never called during prerender, so the polling
+        // loop only starts once the page is truly interactive.
+        if (firstRender)
+        {
+            _cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(_cts.Token);
+        }
+
+        return Task.CompletedTask;
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken ct)
+    {
+        while (!ct.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(5), ct);
+
+            var lastId = _notifications?.Count > 0
